    std::vector<i128> qv((size_t)R * R), tv((size_t)R * R);""",
              """    std::vector<std::vector<Opt> > opts(S1);
    std::vector<i128> qv(S1), tv(S1);""")
s = s.replace("""            opts[(size_t)i * R + j] = interval_options(v.starts, i, j, pc);
