            tv[(size_t)i * R + j] = T[(size_t)i * R + j];""",
              """            opts[(size_t)i * (R + 1) + j] = interval_options(v.starts, i, j, pc);
            qv[(size_t)i * (R + 1) + j] = Q[(size_t)i * (R + 1) + j];
            tv[(size_t)i * (R + 1) + j] = T[(size_t)i * (R + 1) + j];""")
s = s.replace("""            const std::vector<Opt>& os = opts[(size_t)i * R + t];
            i128 tt = tv[(size_t)i * R + t], qq = qv[(size_t)i * R + t];""",
              """            const std::vector<Opt>& os = opts[(size_t)i * (R + 1) + t];
            i128 tt = tv[(size_t)i * (R + 1) + t], qq = qv[(size_t)i * (R + 1) + t];""")
s = s.replace("""                        i128 work = tt * (cached ? pc.hit : pc.miss) * o.P + (i128)o.coeff * qq;""",
              """                        i128 work = tt * (cached ? pc.hit : pc.miss) * o.P + (i128)o.coeff * qq;""")
open('plan.hpp','w').write(s)
print("ok")
